using StrataLint.Scribe;
using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ObserverMemory.Algorithms.KBonacciAcquisition;

internal sealed class OriginalScheduledWitnessTablesDocument : IScribeDocumentDefinition
{
    private const string Owner =
        "D5/S3/ObserverMemory/Algorithms/KBonacciAcquisition/OriginalScheduledWitnessTables.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual witness executions extract a common finite scheduled table law.",
        H("Actual witness tables for preselected and stopped acquisitions"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("scheduled-witness-view"),
                DeclarationHandle.Create(Owner + "view"),
                H("Chronological schedule cells"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For an arbitrary address type, Boolean stop mode, finite address list and static Boolean response map, view returns every scheduled reply in order. In stopped mode it includes the first false reply and omits everything after it. In preselected mode it retains every reply, including repeated addresses and reversed pairs."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-view-congr"),
                DeclarationHandle.Create(Owner + "view_congr"),
                H("Chronological view congruence"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every address type A, stop mode, finite list xs and Boolean reply maps q,r on A, agreement q(i)=r(i) for every occurrence i in xs implies view stop xs q equals view stop xs r. List induction retains order, repetitions and first-false stopping. Equal-rank chain words use this congruence through the actual catalog factorization."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-step"),
                DeclarationHandle.Create(Owner + "step"),
                H("Actual requests and silent processing"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("An arbitrary configuration C contains the eventual original tape. A source-free instruction reads an arbitrary natural address, silently updates C, or halts. The adapter to StateTransition appends exactly one address-reply pair at every read, including a duplicate. Silent updates preserve this log. There is no countability, computability, measurable-space or transition-time hypothesis on C. The update epochs of GuardedPhaseExecution are not request counts."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-disciplined"),
                DeclarationHandle.Create(Owner + "Disciplined"),
                H("Reachable next-query discipline"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For each fixed seed and source, a reachable read must be the next entry of the seed-preselected schedule, after the entire chronological address log. In stopped mode every earlier recorded reply must be true. Silent processing is unrestricted. This necessary local condition follows directly from either original schedule contract; it also permits early handoff, so the extraction theorem covers those rules too. It assumes no equality of executions, terminal factorization or finite table membership. A read after a queried zero is excluded by its local premise."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-lowschedule"),
                DeclarationHandle.Create(Owner + "lowSchedule"),
                H("Retaining original low addresses"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Filter a finite schedule by address less than L, preserving order and repeats. Natural address i means original prime index i+1. The filtered length is at most the original length, and a strictly increasing original list remains strictly increasing."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-lowreply"),
                DeclarationHandle.Create(Owner + "lowReply"),
                H("Finite input words"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A word b on Fin L gives its actual Boolean reply below L. The default value outside this range is false and serves only to evaluate low schedules. This is an offline finite table definition, not an additional observation available to the acquisition."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-incatalog"),
                DeclarationHandle.Create(Owner + "InCatalog"),
                H("The complete restricted output catalog"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For any stop mode and L, a finite output function belongs to the catalog when some at-most-two low-address schedule determines it through its reply cell. The stopped schedule is strictly increasing. Every cell may have any label in Fin(L+1), independently of whether its mark was queried. The preselected pair has all four cells 00,01,10,11; repeats have diagonal information and reversal preserves its actual order. The stopped pair has cells 0,10,11, so words 00 and 01 share one cell. Empty and singleton schedules are included, as is L=0."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-witnesstable"),
                DeclarationHandle.Create(Owner + "witnessTable"),
                H("One whole-table gate"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For a seed event D, measurable sourcewise terminal maps phi and marked projection rho, the whole output table at s evaluates rho(phi(b,s)) for every b on D. Off D the entire table is the constant base label zero. Thus every input uses the same gate and the same original seed. The witness executions used to define this table are fixed actual comparison sources chosen before seeds; evaluating them is not a live source acquisition."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-catalog"),
                DeclarationHandle.Create(Owner + "Catalog"),
                H("Finite representatives and a common law"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The catalog is the subtype of all complete word-to-label functions satisfying InCatalog. It is finite because both the word set and label set are finite. A representing schedule may be fixed once for each function by its defining existential. Pushing one seed law to this subtype gives one PMF of whole tables, rather than separate distributions for different input words."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-schedulegate"),
                DeclarationHandle.Create(Owner + "scheduleGate"),
                H("A common schedule bound"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("At cutoff c, scheduleGate is the event that every preselected address is strictly less than c. Its measurability is the required consequence of measurable finite schedule selection. Its complement decreases to the empty set, because each individual seed chooses a finite schedule. No handoff time or configuration measurability is involved."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("scheduled-witness-approximation"),
                DeclarationHandle.Create(Owner + "scheduled_witness_approximation"),
                H("One common catalog law approximates every actual witness row"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Fix arbitrary measurable seed and tape spaces S and Theta, an arbitrary configuration type C, a probability measure mu, active length L and Boolean stop mode. Fix one seed-dependent schedule, initialization and source-free instruction function, and a source-free terminal readout from C to Theta. For each m and each complete low word b, fix a static actual-witness response map q, a measurable terminal extension phi, a measurable conull termination event T, and an original target measure. Set cutoff c=L+1+m. The response is b below L and false on L through c-1. Require at most two schedule entries, strict increase in stopped mode, measurable schedule sublevel events, local reachable read discipline, finite evaluation on T, and equality of the terminal configuration readout with phi there. Require measurable rho from the full tape space to Fin(L+1), and the original sourcewise cap in supremum-over-events TV.")),
                    Paragraph(Text("Let H_m be the one schedule event and D_m=H_m intersect the intersection of T_m,b over all low words. The theorem gives gamma_m=mu(H_m complement) tending to zero. For every m it constructs a measurable F_m:S to Catalog and one PMF w_m, with w_m.toMeasure=mu.map(F_m). Its entire function at every seed is the gated witnessTable. The failure mass is exactly mu(D_m complement)=gamma_m, and every row of the same w_m obeys TV(row_b,rho_*target_m,b)<=eps+gamma_m. No monotonicity of D_m is claimed; the actual comparison witnesses can change with m.")),
                    Paragraph(Text("For replay relate equal configurations and equal chronological logs reachable in the first execution. Every recorded reply equals its source response. At a reachable next query the local schedule decomposition identifies its position; equality of preselected views, or of stopped views before a shared first zero, identifies that reply. The resulting local Respects relation is consumed by Mathlib StateTransition.tr_eval. It preserves the terminal configuration and therefore its original tape. Removing fixed high false replies preserves equality of low views. Filtering the schedule then proves catalog membership. This is local queried-cell replay: entire-prefix source agreement from Lemma 45.3 is not used in its place.")),
                    Paragraph(Text("Finite coordinate measurability makes F_m measurable. All finite termination events intersect conullly, so discarding them adds no failure mass. On D_m every row equals the projected actual terminal map; event preimage inclusions bound its TV discrepancy by gamma_m. Triangle inequality and measurable TV contraction give the cap estimate. The TV object is the supremum of the maximum of both truncated event-mass differences in ENNReal, with no factor of two. For probability laws its real value is the original event-supremum absolute difference, and eps is the nonnegative real cap embedded in ENNReal."))),
                DescribeRole.Theorem),
            new DocumentBlock.Section(H("Common-seed application with false-padded prefixes"), Blocks(
                Paragraph(Text("Fix one probability seed space (S,mu), a configuration type C, a measurable tape space Theta, a source-free instruction prog:S to C to Instruction C Nat Bool, initialization initial:S to C, terminal readout:C to Theta, and a finite preselected schedule(s). Actual responses q(x,i) are static Boolean maps of the source x and address i. Initialization, instructions and readout cannot inspect x except through these replies. No probability distribution on sources is used. For every finite prefix length M and Boolean word w on Fin M, choose an actual source a(M,w) realizing that prefix, before sampling any seeds. The indices (M,w) form the countable dependent sum of the finite word sets. Although a matching witness will be picked when analyzing a fixed seed, all witnesses and their good events already belong to this fixed countable family. For OriginalScheduledRealization.Source one may instead intersect over the entire actual source space: it is a subtype of Nat times Int and hence countable.")),
                Paragraph(Text("For each selected actual source x assume a measurable conull event E_x on which its execution terminates, satisfies actual local Disciplined, and has chronological charged-log length at most k. Every read, including a repeat, contributes one log entry. Assume measurable actual terminal-output extensions agreeing with readout on E_x, or measurable projected extensions for each needed rho_L. Also include every selected gated witness x_(L,m,b), with its measurable conull termination and output-agreement event T_(L,m,b). Let B be a measurable conull schedule-lawfulness event when lawfulness is only almost sure. Define G=B intersect the intersection of all E_x and all T_(L,m,b). The indices L,m and their finite word sets are countable, so G is measurable and conull by countable intersection and ae_all_iff. This single G is used for every length, every gate and every counterfactual response map.")),
                Paragraph(Text("For the original N and O applications, B must give the actual schedule-length bound length(schedule(s))<=2; O also requires strict increase. A terminal hard budget by itself does not give this interface: a procedure may halt immediately while carrying an unused schedule of any finite length. The current scheduled_witness_approximation signature requires bounded schedules and discipline for every seed, whereas its terminal condition is restricted to T. Sourcewise almost-sure primitive conditions therefore cannot be passed directly to its forall-seed binders. Work on the measurable subtype G with its induced probability measure, then extend the constructed tables by zero on its null complement. Alternatively, first justify an everywhere-normalized modification of the primitive inputs. The subtype route preserves the original seed law after extension and does not require any discipline assertion outside G.")),
                Paragraph(Text("Fix s in G and any static counterfactual q_cf:Nat to Bool. Choose M strictly above every entry of schedule(s), and take the already selected actual witness a(M,q_cf restricted to Fin M). Its replies agree with q_cf at every scheduled occurrence, so view_congr gives equality of their full chronological views. Apply the original replay with this ACTUAL response map as its first oracle, q_cf as its second, the actual discipline on G, and its actual terminal execution. The returned terminal object is the identical pair of control C and full charged log. In particular the terminal tape, the length bound k and repeat counting transfer. The proof never assumes counterfactual Disciplined. It supplies a genuinely finite terminating execution, so finite reads followed by infinite silent updates are excluded as well. StateTransition.mem_eval identifies finite reachability and halt, and uniqueness of eval fixes the terminal object independently of the chosen matching actual witness. Replay permits any finite schedule and uses no transition cutoff; this observation creates no new general-k catalog.")),
                Paragraph(Text("For a word b on Fin L, lowReply b is b below L and false at every higher address. Let rho_L:Theta to Fin(L+1) be measurable, and define F_L(s)(b) on G as rho_L of the readout of the unique terminal control for lowReply b; off G set the whole table to zero. To establish measurability, for increasing prefix lengths M use the preselected actual witnesses a(M,(lowReply b) restricted to Fin M). At each fixed s in G, every sufficiently long prefix contains its entire finite schedule, so replay gives exactly the same terminal control and full log as lowReply b. This is eventual equality, not merely convergence in distribution.")),
                Paragraph(Text("Mask EACH measurable actual projected-output approximant with the SAME measurable event G and assign zero off G. On G its row is eventually equal to F_L(s)(b); off G both the entire sequence and the limit are identically zero. The masked sequence therefore converges pointwise at EVERY seed in the finite discrete label space. measurable_of_tendsto_metrizable proves measurable rows, and measurable_pi_lambda gives the measurable full table F_L. No measurable structure on C, joint measurability of counterfactual executions, completeness of mu, or selection of an arbitrary almost-everywhere limit is needed. An unmasked almost-everywhere limit would not justify this measurable conclusion on an incomplete seed space.")),
                Paragraph(Text("For the <=2 original classes, the resulting F_L(s) belongs to the existing InCatalog stop L. At a fixed good seed take a cutoff above L and the entire schedule and choose the finitely many actual witnesses matching the false-tail words to that cutoff. The original lowSchedule, view_filter, actual_witness_table_class and replay factor their equal terminal outputs through low views. Equivalently, on G the gated tables below eventually equal the whole F_L(s); their existing catalog membership transfers through equality. Outside G the constant-zero table has the empty schedule as representative. N retains arbitrary preselected pairs, repetitions and order; O retains increasing stopped schedules. The arbitrary-k replay observation does not enlarge Catalog or change either class.")),
                Paragraph(Text("For L<=K define pi_(K,L):Fin(K+1) to Fin(L+1) by retaining a label j when j<=L and sending every other label to zero. It fixes zero, has identity pi_(L,L), and composes as pi_(K,L) after pi_(J,K)=pi_(J,L). Require rho_L=pi_(K,L) composed with rho_K on the FULL tape carrier Theta. The singleton-mark projections described below satisfy this: a retained positive mark keeps its label, a discarded mark and every unmarked tape have label zero. Compatibility only on a proposed output support would not suffice for arbitrary terminal readout.")),
                Paragraph(Text("Pad b on Fin L by false on the remaining coordinates of Fin K, denoting the result pad_(K,L)b. Then lowReply(pad_(K,L)b)=lowReply b as entire Nat response maps, including every address at or above K. Define restriction_(K,L)(f)(b)=pi_(K,L)(f(pad_(K,L)b)). The unique terminal control for these identical oracles is identical; full-carrier projection compatibility gives F_L(s)=restriction_(K,L)(F_K(s)) on G. The same equality holds off G because pi_(K,L)(0)=0. Identity and composition of restrictions follow from the corresponding projections and false padding. Thus for W_L=mu.map F_L the finite laws satisfy (W_K).map restriction_(K,L)=W_L by Measure.map_map, always using the SAME original mu. These are laws on complete finite tables; catalog subtype laws give the same identities after the faithful subtype inclusion. This is false-padded-prefix coherence. It asserts neither invariance under arbitrary high bits nor preservation of all output laws of an arbitrary original N competitor.")),
                Paragraph(Text("Now fix L and retain the actual gated witnesses x_(L,m,b), the same original mu, prog, initial and readout, and cutoff c=L+1+m. Let H_(L,m)=scheduleGate(schedule,c) and D_(L,m)=H_(L,m) intersect the intersection of T_(L,m,b) over b. The original gated table F_(m,L) is witnessTable on D_(L,m), with its common zero value outside. The construction of G includes EVERY such T. For s in G intersect H_(L,m), these actual witnesses agree with lowReply b at every scheduled occurrence; actual-first replay identifies each terminal control and log. Consequently the WHOLE tables F_(m,L)(s) and F_L(s) are equal, simultaneously for all b. On a subtype-G application, the corresponding zero extensions obey precisely the same comparison; when the original full-space forall-seed hypotheses are available, its directly supplied tables have this equality too.")),
                Paragraph(Text("Apply the original private gate_tv with full-table codomain, f=F_(m,L), g=F_L, and comparison event G intersect H_(L,m). Countable conullity gives mu((G intersect H_(L,m)) complement)=mu(H_(L,m) complement)=gamma_(L,m); this also follows from Measure.measure_inter_eq_of_ae and the measurable complement formula. Therefore TV(W_(m,L),W_L)<=gamma_(L,m). The original schedule argument, using tendsto_measure_iInter_atTop, gives gamma_(L,m) tending to zero for each FIXED L because every seed's preselected schedule is finite. There is one exceptional event for the whole table, with no factor 2^L and no 1/m transition cutoff. No uniform rate in L, comparison between competing schedules, or coupling of different seed spaces is asserted. A table and its catalog subtype representative must use the same entries and the same zero extension; equality of marginal row laws alone would not justify this whole-table application.")),
                Paragraph(Text("A closed cap additionally requires the actual-source cap and a projected target beta_(L,b) that is EXACTLY independent of m. If only approximate target agreement is available, its error must be added explicitly and controlled in the limit. From the existing projected gated-row estimate TV(row_b(W_(m,L)),beta_(L,b))<=eps+gamma_(L,m), measurable TV contraction under row evaluation and the whole-table comparison give TV(row_b(W_L),beta_(L,b))<=eps+gamma_(L,m)+gamma_(L,m). The two gate errors must both be counted: this route gives eps+2gamma, not eps+gamma. In ENNReal, triangle inequality, addition continuity and le_of_tendsto_of_tendsto yield the closed bound eps as m tends to infinity.")),
                Paragraph(Text("There is also a direct comparison: on G intersect H_(L,m), each F_L row equals the measurable projected ACTUAL witness output. Applying gate_tv to that row and TV contraction to the actual-source cap gives eps+gamma_(L,m), with the same fixed target beta_(L,b), and hence the same closed limit eps. This direct bound does not remove either error from the distinct two-step comparison through W_(m,L). The common-seed construction uses no compactness subsequence. It is an application of replay, gating and measurable limits; the signature of scheduled_witness_approximation itself states the gated approximation and does not state this combined limit construction.")),
                Paragraph(Text("Finite-pattern realization by actual Source, measurable singleton-mark projections on the full carrier, the fixed projected target image, and the exact full-carrier tail maximum max(1-p0,a_n) are separate application inputs described in the owning source and realization documents. The common-seed derivation above requires those inputs and their parameter maps; it does not replace their arithmetic, target or full-tail obligations with an assumed final transport statement. In particular coherence supplies no sharp head capacity, equality-face maximality, positive-slack N-to-O selection or original nonatomic-target conclusion. The original comparison (110.14) permits replacing the entire feasible mixed kernel: for each given (a,eps), one O law and program must work on EVERY actual source. It requires neither preservation of an arbitrary input N law nor one O law independent of eps and L. The coherent finite laws alone do not implement or establish that comparison.")))),
            new DocumentBlock.Section(H("Original Fibonacci sources and limits"), Blocks(
                Paragraph(Text("For the actual source take q_m,b(i)=1[p_(i+1) divides 1+F_r g], with r prime and ceil(F_r/10)<=g<=floor(F_r/5). FiniteFibonacciRankClosure directly supplies rankWitness. Applying Mathlib finite CRT and FibonacciRank.fibonacci_entry_point to these ranks supplies the finite-pattern window assembly: at K=1, one common R works for every prime r>=R and every Boolean pattern, with positive N. The whole finite family is fixed before seeds. Apply it to the first c primes, retaining b below L and zero at the other c-L addresses. In particular an all-positive low word has actual first absence L+1, rather than being an infinite all-positive source. The terminal maps and conull events are the sourcewise extensions of Definition 45.1. Take the full original disjoint union of B_j and P_j interval blocks as Theta, with marks theta_j=(B_1,1/(j+2)); rho fixes the retained positive marks and sends every other tape to label zero. No competitor output-support restriction is imposed.")),
                Paragraph(Text("Represent the entire original tape carrier by the sum of two copies of PNat times the real open unit interval. The measurable equivalence sumProdDistrib identifies it bijectively with a pair consisting of a tagged positive block index and an interval coordinate. The positive-index coordinate has its discrete sigma algebra; measurable_from_prod_countable_right identifies measurable blockwise maps with maps on this countable disjoint union. No interval coordinate is removed. The original consumer is Sum.elim of constant unknown on the left and the positive block index proposal on the right. Every theta_j has left tag, index one, and coordinate 1/(j+2), so the unchanged consumer returns unknown at every mark.")),
                Paragraph(Text("Reciprocal injectivity and natural-number casting give distinct marks. Their singletons are Borel measurable, as are finite unions and images. Embed Fin(L+1) by j to theta_j; this finite injective map is a measurable embedding. Define rho as Function.extend of its inverse labels with constant zero outside its range. MeasurableEmbedding.measurable_extend proves measurability on the full carrier. Injective.extend_apply gives rho(theta_j)=j for j<=L, and extend_apply' gives zero at every other tape. Including theta_0 in the embedding only assigns the same default label zero to that base point.")),
                Paragraph(Text("Use zero-based natural addresses: i reads p_(i+1), and a(i) denotes the original amplitude a_(i+1). For every actual source, positive N follows from its window lower bound. A prime larger than N cannot divide it, so Nat.find defines its least false address. For a low word b, define k as the least false address of lowReply b; it satisfies k<=L. The witness's actual first false address equals k: the low answers coincide below L and the forced answer at L is false. Thus a low zero gives actual first absence k+1, while an all-positive low word gives exactly L+1. This includes L=0 and retains every later-zero pattern.")),
                Paragraph(Text("Write the original selected measure as ofReal(1-a(k))*dirac(theta_0)+ofReal(a(k))*dirac(theta_(k+1)). Antitonicity and a(0)<=1 derive every needed amplitude upper bound from the original sequence contract. Map addition, scalar multiplication and Dirac measures through rho. If k<L, its image is the retained two-point eta_b; if k=L, both atoms map to zero and their coefficients sum to one, giving delta_0. This proves fixed eta_b independently of m, rather than assuming it. With these actual-source and target inputs, scheduled_witness_approximation supplies gated cap estimates. The common-seed construction above gives the exact cap-feasible law on the same restricted catalog; finite simplex compactness is an alternative for finite feasibility alone.")),
                Paragraph(Text("Each finite cap bounds both directed event discrepancies. Test the base singleton, the first-zero singleton, and their union separately. The resulting three inequalities are ofReal(1-a(k))<=eps+p_b({0}), ofReal(a(k))<=eps+p_b({k+1}), and 1<=eps+p_b({0,k+1}). The all-positive row is 1<=eps+p_b({0}). The pair row is an independent event test, with no inference from only singleton constraints. For probability measures and a nonnegative real cap, converting these finite ENNReal inequalities to real values gives the original closed rows without a factor of two. The necessity conclusion concerns finite feasibility and does not preserve every law of an arbitrary original competitor.")),
                Paragraph(Text("Definition 90.1 supplies the schedule discipline with all actual requests counted; its prescribed exhaustion and first-zero stopping imply the weaker local conditions used here. The original deterministic procedure supplies C, initial and prog after fixing the seed, with its terminal tape in C. Initialization and actions use the common seed and fixed zero advice; the source label, numerical N, first absence, target law and extra observations are absent. Only a read reply depends on the actual source. The interpreter retains arbitrary silent processing before and after reads. The extracted comparison tables do not run the consumer. OriginalScheduledRealization supplies the actual execution and same-source consumer handoff.")),
                Paragraph(Text("The unit proves class-preserving whole-table approximation, not Theorem 110.2's full equivalence. For fixed projected targets eta_b, an alternative compactness argument obtains closed-cap finite feasibility from the approximation: enumerate the finite catalog by Fin N, regard its PMFs as probability measures, and take a convergent subsequence in the compact simplex. Every discrete event mass is continuous; rewriting each TV constraint as its two event inequalities and passing to the limit gives TV(row_b,eta_b)<=eps for every word. Mapping the limit weights back through the enumeration keeps the same restricted catalog. For the original selected laws, this closed-cap application uses the full-carrier projection and first-absence parameter map above. OriginalScheduledRealization supplies actual scheduled prime reads and same-source marked-tape handoff. The OriginalScheduledRealization application combines a uniform interval sampler with the exact full-tail maximum identity and strict active cutoff, including the equality tail endpoint, to realize every cap-feasible distribution on the appropriate restricted catalog. Identifying the stopped catalog laws with the coefficient criterion O_L=C_L of Section 109.1 remains separate. L=0 is present in the theorem without a positive-length hypothesis. This result preserves feasibility information, not arbitrary original competitor laws, and gives no unrestricted N/O separation.")))))));
}
